import{_ as a,a as s,c as i,ac as t}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"Redis 键管理：数量、扫描与过期时间","description":"集中说明键存在性、库内数量、SCAN 与 TTL。","frontmatter":{"title":"Redis 键管理：数量、扫描与过期时间","description":"集中说明键存在性、库内数量、SCAN 与 TTL。","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","summary":"集中说明键存在性、库内数量、SCAN 与 TTL。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"middleware/redis/key-lifecycle.md","filePath":"middleware/redis/key-lifecycle.md"}'),n={name:"middleware/redis/key-lifecycle.md"};function d(l,e,r,p,c,o){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="redis-键管理-数量、扫描与过期时间" tabindex="-1">Redis 键管理：数量、扫描与过期时间 <a class="header-anchor" href="#redis-键管理-数量、扫描与过期时间" aria-label="Permalink to &quot;Redis 键管理：数量、扫描与过期时间&quot;">​</a></h1><h2 id="part-1" tabindex="-1">Redis 键与过期时间 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;Redis 键与过期时间 {#part-1}&quot;">​</a></h2><p>键用于定位数据。可以使用 <code>app:对象:编号:字段</code> 这样的命名约定，例如 <code>shop:user:42:name</code>；冒号只是方便人阅读，不会自动创建目录或提供权限隔离。</p><h3 id="part-1-查询键" tabindex="-1">查询键 <a class="header-anchor" href="#part-1-查询键" aria-label="Permalink to &quot;查询键 {#part-1-查询键}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>TYPE key</code></td><td>查看值类型；键不存在时返回 <code>none</code></td></tr><tr><td><code>EXISTS key</code></td><td>检查键是否存在</td></tr><tr><td><code>TTL key</code> / <code>PTTL key</code></td><td>查看剩余秒数 / 毫秒数</td></tr><tr><td><code>DEL key</code></td><td>删除指定键</td></tr></tbody></table><h3 id="part-1-设置与保留过期时间" tabindex="-1">设置与保留过期时间 <a class="header-anchor" href="#part-1-设置与保留过期时间" aria-label="Permalink to &quot;设置与保留过期时间 {#part-1-设置与保留过期时间}&quot;">​</a></h3><p><code>SET key value EX 60</code> 在写入时设置 60 秒有效期，<code>EXPIRE key 60</code> 为已有键设置有效期。<code>TTL</code> 返回 <code>-1</code> 表示没有过期时间，<code>-2</code> 表示键不存在；返回非负整数表示剩余秒数。</p><p>普通 <code>SET</code> 覆盖值会清除原来的 TTL；<code>SET ... KEEPTTL</code> 可保留。<code>INCR</code>、<code>HSET</code> 等修改值内容的操作不会重置整个键的 TTL。<code>PERSIST</code> 移除整个键的过期时间。</p><p>下面是独立实验服务中的练习步骤，输出是预期结果，本次文档整理未运行这些命令：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET learn:ttl value EX 60</span></span>
<span class="line"><span>TTL learn:ttl</span></span>
<span class="line"><span>SET learn:ttl replacement</span></span>
<span class="line"><span>TTL learn:ttl</span></span>
<span class="line"><span>EXPIRE learn:ttl 60</span></span>
<span class="line"><span>SET learn:ttl final KEEPTTL</span></span>
<span class="line"><span>TTL learn:ttl</span></span>
<span class="line"><span>DEL learn:ttl</span></span>
<span class="line"><span>TTL learn:ttl</span></span></code></pre></div><p>及时执行时，第一次 TTL 为 0 到 60 之间；普通覆盖后为 <code>-1</code>；保留 TTL 后继续倒计时；删除后为 <code>-2</code>。中途等待超过有效期，结果也会变化。</p><h3 id="part-1-查找一组键" tabindex="-1">查找一组键 <a class="header-anchor" href="#part-1-查找一组键" aria-label="Permalink to &quot;查找一组键 {#part-1-查找一组键}&quot;">​</a></h3><p>从 <code>SCAN 0 MATCH learn:* COUNT 100</code> 开始，使用返回的游标继续扫描，直到游标回到 <code>0</code>。<code>COUNT</code> 是工作量提示，不能把一次空结果当成扫描完成；并发变化时还需处理重复结果，扫描不提供快照。</p><p>不要把线上全量查键当成普通请求路径。大键空间上的 <code>KEYS *</code> 会阻塞命令处理，排查时优先分批扫描，并限制后续读取的数据量。</p><p>继续阅读：<a href="/middleware/redis/data-operations#part-1-ttl">TTL、覆盖与缓存行为</a>。参考：<a href="https://redis.io/docs/latest/commands/expire/" target="_blank" rel="noopener noreferrer">EXPIRE</a>、<a href="https://redis.io/docs/latest/commands/scan/" target="_blank" rel="noopener noreferrer">SCAN</a>。</p><h2 id="part-2" tabindex="-1">Redis 键数量查询 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;Redis 键数量查询 {#part-2}&quot;">​</a></h2><p><span id="part-2-redis-utils"></span></p><h3 id="part-2-redis-工具" tabindex="-1">redis 工具 <a class="header-anchor" href="#part-2-redis-工具" aria-label="Permalink to &quot;redis 工具 {#part-2-redis-工具}&quot;">​</a></h3><h3 id="part-2-查询多少key" tabindex="-1">查询多少key <a class="header-anchor" href="#part-2-查询多少key" aria-label="Permalink to &quot;查询多少key {#part-2-查询多少key}&quot;">​</a></h3><p>下方地址、键名和数量来自原笔记历史会话，本轮未连接该实例；不要把固定数量当作当前环境的预期值。</p><ul><li><code>INFO keyspace</code>：查看各非空库的键统计</li><li>dbsize：当前库key 数量</li><li><strong>keys</strong> 线上不推荐</li></ul><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 本地虚构数据示例</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyspace</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Keyspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">db0:keys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=10,expires=2,avg_ttl=60000</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">del</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example:task</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1</span></span></code></pre></div>`,22)])])}const g=a(n,[["render",d]]);export{k as __pageData,g as default};
